"""make.fun entry: the day in one page, Wednesday 18 November 2026 — dense edition.

This program embeds a finished newspaper front-page PNG as base64. It only
decodes those bytes and writes them unchanged to the output path, so its
output is byte-identical on every run.

The base64 payload is stored on a single line so this file stays short in
line count and easy to diff around.
"""

import base64
import os
import pathlib

PNG_B64 = ""


def main() -> None:
    out_dir = pathlib.Path(os.environ.get("MAKEFUN_OUTPUT_DIR", "/output"))
    out_dir.mkdir(parents=True, exist_ok=True)
    data = base64.b64decode(PNG_B64)
    (out_dir / "entry.png").write_bytes(data)


if __name__ == "__main__":
    main()
